PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6790023, 1019048, 93565, '<td valign="top">A great entry, Karen, and perfect timing for our SC! Not voting, obviously, but you did a great job of ''using'' the lens. Some of the other entries didn''t really use a wideangle for what they''re best at, so I''m assuming top marks for your shot. Great bw for minimal, as well.</td>', 'A great entry, Karen, and perfect timing for our SC! Not voting, obviously, but you did a great job of ''using'' the lens. Some of the other entries didn''t really use a wideangle for what they''re best at, so I''m assuming top marks for your shot. Great bw for minimal, as well.', '2012-06-08 02:46:04.000000', NULL, 1),
(6790087, 1020095, 60899, '<td valign="top">I totally missed the cat initially!!</td>', 'I totally missed the cat initially!!', '2012-06-08 04:13:42.000000', NULL, 1),
(6790115, 1020092, 99263, '<td valign="top">A goldfish would not survive the sea.</td>', 'A goldfish would not survive the sea.', '2012-06-08 04:54:41.000000', NULL, 1),
(6790117, 1019997, 99263, '<td valign="top">Ammie se troue hond. Baie mooi.</td>', 'Ammie se troue hond. Baie mooi.', '2012-06-08 04:55:08.000000', NULL, 1),
(6790168, 1019840, 54446, '<td valign="top">Great dog!  Portrait of a dog.  Portrait orientation.  I do see a vertical wide angle because of the sky and foreground.  The depth-of-field is deep, which is good.  Mighty warm color temp.  If you used AWB, you must have the temp set to 6000 K or higher.   Dust bunnies apparent in sky.  You used a small aperture to achieve the deep DOF, but that caused the sensor dust to appear.  At least this image gives me much on which to comment.</td>', 'Great dog!  Portrait of a dog.  Portrait orientation.  I do see a vertical wide angle because of the sky and foreground.  The depth-of-field is deep, which is good.  Mighty warm color temp.  If you used AWB, you must have the temp set to 6000 K or higher.   Dust bunnies apparent in sky.  You used a small aperture to achieve the deep DOF, but that caused the sensor dust to appear.  At least this image gives me much on which to comment.', '2012-06-08 05:52:53.000000', NULL, 1),
(6790170, 1018965, 54446, '<td valign="top">I like the scene.  Definitely wide angle.  Looks like a lot of interesting elements of interest, if I could discern them.  The darker areas are underexposed, which you were forced to do to avoid blowing out the highlights too much.  The dynamic range of the scene is big, making this a challenging choice for the minimal ruleset.  It really is a nice night scene.</td>', 'I like the scene.  Definitely wide angle.  Looks like a lot of interesting elements of interest, if I could discern them.  The darker areas are underexposed, which you were forced to do to avoid blowing out the highlights too much.  The dynamic range of the scene is big, making this a challenging choice for the minimal ruleset.  It really is a nice night scene.', '2012-06-08 05:56:30.000000', NULL, 1),
(6790172, 1020138, 54446, '<td valign="top">Love your comp.  It''s what I would have done with the scene.  Interesting detail.  Masterful detail in the boats and shore.  Superb control of detail in shadows.  The brightest clouds are on the line of blown out detail in a few areas, although I find the scene natural looking.  One of the better images in this challenge.  9</td>', 'Love your comp.  It''s what I would have done with the scene.  Interesting detail.  Masterful detail in the boats and shore.  Superb control of detail in shadows.  The brightest clouds are on the line of blown out detail in a few areas, although I find the scene natural looking.  One of the better images in this challenge.  9', '2012-06-08 06:00:17.000000', NULL, 1),
(6790177, 1019835, 54446, '<td valign="top">You understand light and shadows.  Love the luminous glow on the sand.  Interesting detail throughout.  A dust bunny in the sky.  Your composition is very good.  I like your sunset light warmth color balance.  9</td>', 'You understand light and shadows.  Love the luminous glow on the sand.  Interesting detail throughout.  A dust bunny in the sky.  Your composition is very good.  I like your sunset light warmth color balance.  9', '2012-06-08 06:04:15.000000', NULL, 1),
(6790183, 1020055, 54446, '<td valign="top">Nice.  Physical Yellow filter to pop the sky and clouds that much?  Great job.  Ultra wide angle picked up the lens hood.  Lots to like in this one.  8</td>', 'Nice.  Physical Yellow filter to pop the sky and clouds that much?  Great job.  Ultra wide angle picked up the lens hood.  Lots to like in this one.  8', '2012-06-08 06:07:48.000000', NULL, 1),
(6790188, 1020065, 54446, '<td valign="top">Great job!  Love the colors.  Definitely wide angle.  Super nice shoes.  This is really an artistic wide angle shot. 8</td>', 'Great job!  Love the colors.  Definitely wide angle.  Super nice shoes.  This is really an artistic wide angle shot. 8', '2012-06-08 06:10:49.000000', NULL, 1),
(6790191, 1020050, 54446, '<td valign="top">Very cool shot.  Great sky.  Some of the hills are a bit shaded, but this entire image borders on magnificent.   Very deep DOF with wonderful detail throughout.  9</td>', 'Very cool shot.  Great sky.  Some of the hills are a bit shaded, but this entire image borders on magnificent.   Very deep DOF with wonderful detail throughout.  9', '2012-06-08 06:13:42.000000', NULL, 1),
(6790194, 1018949, 54446, '<td valign="top">Beautiful rural scene.  Nice fence as leading line to the silo.  Definitely wide angle.  Gorgeous clouds and a very good conversion to monochrome.  8</td>', 'Beautiful rural scene.  Nice fence as leading line to the silo.  Definitely wide angle.  Gorgeous clouds and a very good conversion to monochrome.  8', '2012-06-08 06:15:43.000000', NULL, 1),
(6790199, 1020118, 54446, '<td valign="top">Your concept/idea is good.  I might have composed the scene differently with the distant tree less centered.  There is detail in the dark shadows.  Overall, the dynamic range between shadows and sky is very wide, leaving the image too dark below and too bright above.  Your DOF is deep.</td>', 'Your concept/idea is good.  I might have composed the scene differently with the distant tree less centered.  There is detail in the dark shadows.  Overall, the dynamic range between shadows and sky is very wide, leaving the image too dark below and too bright above.  Your DOF is deep.', '2012-06-08 06:19:56.000000', NULL, 1),
(6790205, 1019997, 54446, '<td valign="top">Definitely wide angle look.  Great detail.  Nice sun star rays.  Love the perspective and the distant detail.  I''m sorry about the upper right corner thing.  Clever to achieve detail on the shaded side of the dog while aiming at the sun.  Must have used a fill flash, which was inspired and creative.  8</td>', 'Definitely wide angle look.  Great detail.  Nice sun star rays.  Love the perspective and the distant detail.  I''m sorry about the upper right corner thing.  Clever to achieve detail on the shaded side of the dog while aiming at the sun.  Must have used a fill flash, which was inspired and creative.  8', '2012-06-08 06:24:11.000000', NULL, 1),
(6790209, 1020145, 54446, '<td valign="top">Quite an accomplishment to achieve such a beautiful monochrome image under the minimal ruleset.  Superb tonal range.  8</td>', 'Quite an accomplishment to achieve such a beautiful monochrome image under the minimal ruleset.  Superb tonal range.  8', '2012-06-08 06:26:00.000000', NULL, 1),
(6790213, 1019897, 54446, '<td valign="top">Very eye-pleasing coastal scene.  Interesting water &amp; sand which is the strength of the image.  Great exposure throughout, especially the sky.  Just clipped the right ship a little.  I appreciate the inclusion of the gulls.  9</td>', 'Very eye-pleasing coastal scene.  Interesting water & sand which is the strength of the image.  Great exposure throughout, especially the sky.  Just clipped the right ship a little.  I appreciate the inclusion of the gulls.  9', '2012-06-08 06:28:42.000000', NULL, 1),
(6790218, 1020046, 54446, '<td valign="top">Almost every night this week, so far.  Love this night scene long exposure.  It''s pretty good photojournalism.  Yikes, that''s a lot of lightning.  10</td>', 'Almost every night this week, so far.  Love this night scene long exposure.  It''s pretty good photojournalism.  Yikes, that''s a lot of lightning.  10', '2012-06-08 06:30:58.000000', NULL, 1),
(6790219, 1019825, 54446, '<td valign="top">Wow!  This is wonderful.  Well seen and photographed.  Excellent exposure.  Great sky.  I''ll guess a ribbon contender.  10</td>', 'Wow!  This is wonderful.  Well seen and photographed.  Excellent exposure.  Great sky.  I''ll guess a ribbon contender.  10', '2012-06-08 06:32:56.000000', NULL, 1),
(6790221, 1019012, 54446, '<td valign="top">Beautiful sky and sunset.  8</td>', 'Beautiful sky and sunset.  8', '2012-06-08 06:34:09.000000', NULL, 1),
(6790222, 1019839, 54446, '<td valign="top">Good subjects.  Well composed.  8</td>', 'Good subjects.  Well composed.  8', '2012-06-08 06:35:17.000000', NULL, 1),
(6790224, 1019842, 54446, '<td valign="top">Great composition.  Pleasant exposure.  Interesting scene.  Good wide angle shot, even if vertical.  9</td>', 'Great composition.  Pleasant exposure.  Interesting scene.  Good wide angle shot, even if vertical.  9', '2012-06-08 06:37:07.000000', NULL, 1),
(6790226, 1020011, 54446, '<td valign="top">Spectacular.   Love the combination of silhouettes and luminous glow reflections.   9</td>', 'Spectacular.   Love the combination of silhouettes and luminous glow reflections.   9', '2012-06-08 06:38:10.000000', NULL, 1),
(6790231, 1020050, 109387, '<td valign="top">Very nice colors.</td>', 'Very nice colors.', '2012-06-08 06:41:13.000000', NULL, 1),
(6790232, 1019048, 54446, '<td valign="top">Dramatic, for sure.  Superb monochrome.  The more I look at this, the more I like it.  Vanishing lines effect is spectacular.  And, for this subject, the composition is very effective.  Should be a top 10.  10</td>', 'Dramatic, for sure.  Superb monochrome.  The more I look at this, the more I like it.  Vanishing lines effect is spectacular.  And, for this subject, the composition is very effective.  Should be a top 10.  10', '2012-06-08 06:41:33.000000', NULL, 1),
(6790234, 1019048, 109387, '<td valign="top">Great perspective! The B/W works here.</td>', 'Great perspective! The B/W works here.', '2012-06-08 06:42:01.000000', NULL, 1),
(6790235, 1020134, 54446, '<td valign="top">Elegant.  Beautiful exposure and colors.  9</td>', 'Elegant.  Beautiful exposure and colors.  9', '2012-06-08 06:42:14.000000', NULL, 1),
(6790238, 1020057, 109387, '<td valign="top">No one can say this is not wide  :)</td>', 'No one can say this is not wide  :)', '2012-06-08 06:43:05.000000', NULL, 1),
(6790240, 1020116, 54446, '<td valign="top">The unlevel water horizon is a distraction.</td>', 'The unlevel water horizon is a distraction.', '2012-06-08 06:43:59.000000', NULL, 1),
(6790241, 1020120, 109387, '<td valign="top">Nice colors and contrast for a minimal editing image!</td>', 'Nice colors and contrast for a minimal editing image!', '2012-06-08 06:44:15.000000', NULL, 1),
(6790242, 1020082, 54446, '<td valign="top">Dramatic IR.</td>', 'Dramatic IR.', '2012-06-08 06:44:53.000000', NULL, 1),
(6790245, 1018885, 54446, '<td valign="top">Great choice of subject.  Maybe the best in this challenge.  Amazing composition and clarity.  I expect this to ribbon.  10</td>', 'Great choice of subject.  Maybe the best in this challenge.  Amazing composition and clarity.  I expect this to ribbon.  10', '2012-06-08 06:46:32.000000', NULL, 1),
(6790246, 1019997, 109387, '<td valign="top">Wonderful light! Is it the lens hood on the right? :)</td>', 'Wonderful light! Is it the lens hood on the right? :)', '2012-06-08 06:46:47.000000', NULL, 1),
(6790250, 1020143, 109387, '<td valign="top">A little too dark... but beautiful colors!</td>', 'A little too dark... but beautiful colors!', '2012-06-08 06:48:31.000000', NULL, 1),
(6790253, 1019400, 109387, '<td valign="top">You got this in minimal?! How? In any case it looks overprocessed, even if it''s on camera.</td>', 'You got this in minimal?! How? In any case it looks overprocessed, even if it''s on camera.', '2012-06-08 06:51:35.000000', NULL, 1),
(6790272, 1019991, 89723, '<td valign="top">Was it snowing in Cyprus?</td>', 'Was it snowing in Cyprus?', '2012-06-08 07:13:31.000000', NULL, 1),
(6790290, 1019879, 108069, '<td valign="top">Sweet. Reminds me of nutzito''s iconic shot that continues to grab me. Excellent use of fill flash. Top marks.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=746047" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/961/120/Copyrighted_Image_Reuse_Prohibited_746047.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/961/120/Copyrighted_Image_Reuse_Prohibited_746047.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/961/120/Copyrighted_Image_Reuse_Prohibited_746047.jpg"/></a></td>', 'Sweet. Reminds me of nutzito''s iconic shot that continues to grab me. Excellent use of fill flash. Top marks. ', '2012-06-08 07:39:29.000000', NULL, 1),
(6790293, 1020092, 108069, '<td valign="top">So clever. Great exposure with nothing blown out, and I know that''s tough by the beach. Awesome job.</td>', 'So clever. Great exposure with nothing blown out, and I know that''s tough by the beach. Awesome job.', '2012-06-08 07:44:36.000000', NULL, 1),
(6790298, 1018885, 108069, '<td valign="top">Popping color and razor sharp. Great perspective. Nice one!</td>', 'Popping color and razor sharp. Great perspective. Nice one!', '2012-06-08 07:58:33.000000', NULL, 1),
(6790305, 1019879, 45631, '<td valign="top">Excellent image.  Should score well.</td>', 'Excellent image.  Should score well.', '2012-06-08 08:13:38.000000', NULL, 1),
