(6790339, 1020143, 34938, '<td valign="top">Stunning! 8</td>', 'Stunning! 8', '2012-06-08 10:09:11.000000', NULL, 1),
(6790348, 1019467, 43774, '<td valign="top">Nice perspective. I might have gone inside a bit so it''s all bridge and beams. It''s not quite symmetrical which I think would work better for this shot.</td>', 'Nice perspective. I might have gone inside a bit so it''s all bridge and beams. It''s not quite symmetrical which I think would work better for this shot.', '2012-06-08 10:20:59.000000', NULL, 1),
