(6790353, 1018923, 43774, '<td valign="top">Gorgeous!!</td>', 'Gorgeous!!', '2012-06-08 10:26:02.000000', NULL, 1),
(6790443, 1020145, 15711, '<td valign="top">I like the feeling of the old homestead.  Great composition and wide angle focus.</td>', 'I like the feeling of the old homestead.  Great composition and wide angle focus.', '2012-06-08 11:49:06.000000', NULL, 1),
(6790445, 1019997, 15711, '<td valign="top">AWWW  I really like this a lot.</td>', 'AWWW  I really like this a lot.', '2012-06-08 11:49:24.000000', NULL, 1),
