(6792062, 1020134, 12848, '<td valign="top">Stunning picture--especially for a minimal editing challenge. 10.</td>', 'Stunning picture--especially for a minimal editing challenge. 10.', '2012-06-11 01:59:25.000000', NULL, 1),
(6792063, 1019975, 12848, '<td valign="top">Brilliant picture in its simplicity.</td>', 'Brilliant picture in its simplicity.', '2012-06-11 02:00:27.000000', NULL, 1),
(6792283, 1019997, 114233, '<td valign="top">Going to guess it is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=101668" rel="nofollow" target="_blank">Ammie</a>. Getting to know those ploughed fields, mountains, gorgeous golden light... oh and that German Shephard from that 49 steps (I think) challenge!<br/>Super shot Amanda and for minimal editing you have handled the lighting very well. I''m sure some others will moan about that dark area in the top right but it doesnt really bother me because its hardly noticable.<br/>Good luck!</td>', 'Going to guess it is  Ammie. Getting to know those ploughed fields, mountains, gorgeous golden light... oh and that German Shephard from that 49 steps (I think) challenge!Super shot Amanda and for minimal editing you have handled the lighting very well. I''m sure some others will moan about that dark area in the top right but it doesnt really bother me because its hardly noticable.Good luck!', '2012-06-11 08:18:47.000000', NULL, 1),
(6792529, 1018923, 4793, '<td valign="top">Beautiful landscape</td>', 'Beautiful landscape', '2012-06-11 16:41:52.000000', NULL, 1),
(6792530, 1020057, 4793, '<td valign="top">WOW</td>', 'WOW', '2012-06-11 16:42:12.000000', NULL, 1),
(6792811, 1019472, 30982, '<td valign="top">I''m not sold on the tree dead center, though I do love to center things.  I''m more intrigued by the lonley picknic table to the right.</td>', 'I''m not sold on the tree dead center, though I do love to center things.  I''m more intrigued by the lonley picknic table to the right.', '2012-06-12 00:40:00.000000', NULL, 1),
(6792812, 1020128, 30982, '<td valign="top">Nice use of natural framing!  While some may want more "wow" in this, I like the natural greens and grays you have here.  That''s one of the nice side benefits of "minimal".</td>', 'Nice use of natural framing!  While some may want more "wow" in this, I like the natural greens and grays you have here.  That''s one of the nice side benefits of "minimal".', '2012-06-12 00:40:42.000000', NULL, 1),
(6792813, 1019273, 30982, '<td valign="top">Inddeed there are!  A bit vertigo-inducing, but definitely wide!  I particularly like the ripples on the building to the right.  That''s a worthy subject on its own next time you''re out this way.</td>', 'Inddeed there are!  A bit vertigo-inducing, but definitely wide!  I particularly like the ripples on the building to the right.  That''s a worthy subject on its own next time you''re out this way.', '2012-06-12 00:41:26.000000', NULL, 1),
(6792814, 1019975, 30982, '<td valign="top">The slight distortion of the weights does give the feeling of a wide view, but the subject matter doesn''t quite say "wide",  Well lit and photographed.</td>', 'The slight distortion of the weights does give the feeling of a wide view, but the subject matter doesn''t quite say "wide",  Well lit and photographed.', '2012-06-12 00:42:43.000000', NULL, 1),
(6792816, 1020125, 30982, '<td valign="top">Nice catch of the starburst!  Your subject being so centered creates a bit of a static environment, though.</td>', 'Nice catch of the starburst!  Your subject being so centered creates a bit of a static environment, though.', '2012-06-12 00:43:21.000000', NULL, 1),
(6792817, 1019221, 30982, '<td valign="top">Wide and smiling, indeed, though the lion at this angle kind of resembles a zombie...  :-)</td>', 'Wide and smiling, indeed, though the lion at this angle kind of resembles a zombie...  :-)', '2012-06-12 00:44:12.000000', NULL, 1),
(6792818, 1019048, 30982, '<td valign="top">Awesome and VERY wide.  Nice choice to go monochromatic with this - excellent in-camera composition.</td>', 'Awesome and VERY wide.  Nice choice to go monochromatic with this - excellent in-camera composition.', '2012-06-12 00:44:44.000000', NULL, 1),
(6792819, 1020119, 30982, '<td valign="top">Yep, wide, and an interesting composition.  The gray light suits this nicely.</td>', 'Yep, wide, and an interesting composition.  The gray light suits this nicely.', '2012-06-12 00:45:20.000000', NULL, 1),
