(6792828, 1020078, 30982, '<td valign="top">Very nicely composed - indeed has the nice feel of a summer evening with a cool breeze.</td>', 'Very nicely composed - indeed has the nice feel of a summer evening with a cool breeze.', '2012-06-12 00:52:36.000000', NULL, 1),
(6792831, 1019967, 30982, '<td valign="top">Ha!  That''s up close and in-your-lens!  Definitely get the sense of "wide" here.  A bit on the missed focus side but still an interesting photo!</td>', 'Ha!  That''s up close and in-your-lens!  Definitely get the sense of "wide" here.  A bit on the missed focus side but still an interesting photo!', '2012-06-12 00:53:16.000000', NULL, 1),
(6792833, 1019523, 30982, '<td valign="top">What a lovely evening.  I like that this is minimal as it lets the gentle pastels of the evening through without the need to "pump it up" so to speak.</td>', 'What a lovely evening.  I like that this is minimal as it lets the gentle pastels of the evening through without the need to "pump it up" so to speak.', '2012-06-12 00:53:53.000000', NULL, 1),
(6792834, 1019842, 30982, '<td valign="top">Awesome that the water is that clear!  Nice use of wide in the vertical mode, too.</td>', 'Awesome that the water is that clear!  Nice use of wide in the vertical mode, too.', '2012-06-12 00:54:18.000000', NULL, 1),
(6792837, 1020013, 30982, '<td valign="top">I like the use of the tilt here.  This is one where a wee bit of post can probably do a great deal to add to the impact, but I do like the use of monochrome.</td>', 'I like the use of the tilt here.  This is one where a wee bit of post can probably do a great deal to add to the impact, but I do like the use of monochrome.', '2012-06-12 00:56:30.000000', NULL, 1),
(6792839, 1020143, 30982, '<td valign="top">Wow.  That''s pretty darn spectacular.  And this is minimal?  Darn good thing you didn''t get the chance to truly pump up the saturation or it would be overwhelming!</td>', 'Wow.  That''s pretty darn spectacular.  And this is minimal?  Darn good thing you didn''t get the chance to truly pump up the saturation or it would be overwhelming!', '2012-06-12 00:57:12.000000', NULL, 1),
