(6792842, 1019897, 30982, '<td valign="top">Nice use of elements in the wide view - land, sea, boats, birds!</td>', 'Nice use of elements in the wide view - land, sea, boats, birds!', '2012-06-12 00:58:12.000000', NULL, 1),
(6792844, 1019882, 30982, '<td valign="top">Nah, nice balance!  Best part is the three kids watching everyone go by.</td>', 'Nah, nice balance!  Best part is the three kids watching everyone go by.', '2012-06-12 00:58:51.000000', NULL, 1),
(6792845, 1020116, 30982, '<td valign="top">Good use of some foreground elements but you should have had your chainsaw to take out that one tree in the middle third...  :-)  Nice light.</td>', 'Good use of some foreground elements but you should have had your chainsaw to take out that one tree in the middle third...  :-)  Nice light.', '2012-06-12 00:59:43.000000', NULL, 1),
(6792847, 1018803, 30982, '<td valign="top">Love the wiper blade.  Definitely a different take on wide!  Now watch the road...</td>', 'Love the wiper blade.  Definitely a different take on wide!  Now watch the road...', '2012-06-12 01:00:17.000000', NULL, 1),
(6792848, 1020109, 30982, '<td valign="top">Does invoke the feeling of "wide"!  Very nice saturation of the blues, too.</td>', 'Does invoke the feeling of "wide"!  Very nice saturation of the blues, too.', '2012-06-12 01:00:50.000000', NULL, 1),
(6792849, 1018965, 30982, '<td valign="top">I love the young man on the left.  He''s watching you, you know.  Nice color and composition.</td>', 'I love the young man on the left.  He''s watching you, you know.  Nice color and composition.', '2012-06-12 01:01:32.000000', NULL, 1),
(6792850, 1018853, 30982, '<td valign="top">Wonderful!!!  No processing needed.  Joyous, rambunctious.  And his foot right on the corner - serendipitous.</td>', 'Wonderful!!!  No processing needed.  Joyous, rambunctious.  And his foot right on the corner - serendipitous.', '2012-06-12 01:02:10.000000', NULL, 1),
(6792851, 1020118, 30982, '<td valign="top">Love it.  Wonderful composition - shows what you can do with a camera and a great eye.</td>', 'Love it.  Wonderful composition - shows what you can do with a camera and a great eye.', '2012-06-12 01:02:34.000000', NULL, 1),
(6792853, 1020067, 30982, '<td valign="top">A kid''s eye view.  Nice take on the challenge!</td>', 'A kid''s eye view.  Nice take on the challenge!', '2012-06-12 01:02:54.000000', NULL, 1),
(6792854, 1019966, 30982, '<td valign="top">LOL!  A superstar poses for the adoring public.  Great job with the exposure on this.</td>', 'LOL!  A superstar poses for the adoring public.  Great job with the exposure on this.', '2012-06-12 01:03:43.000000', NULL, 1),
(6792855, 1018885, 30982, '<td valign="top">Excellent use of wide!  Nice richness in color, too.</td>', 'Excellent use of wide!  Nice richness in color, too.', '2012-06-12 01:04:01.000000', NULL, 1),
(6792877, 1019824, 30982, '<td valign="top">See, now this is why wide is nice - you can get lots of stuff in the picture to tell the story.  Lovely flow of water, nice green from the trees, your lone fisherman, and even a touch of graffiti, which offers a sad commentary on its own.  Well composed and exposed.</td>', 'See, now this is why wide is nice - you can get lots of stuff in the picture to tell the story.  Lovely flow of water, nice green from the trees, your lone fisherman, and even a touch of graffiti, which offers a sad commentary on its own.  Well composed and exposed.', '2012-06-12 02:06:26.000000', NULL, 1),
(6792878, 1020033, 30982, '<td valign="top">Nice!  Lovely use of the old tree and I like the inclusion of the foreground bit of fence.  Very good job with tricky exposure straight from the camera!</td>', 'Nice!  Lovely use of the old tree and I like the inclusion of the foreground bit of fence.  Very good job with tricky exposure straight from the camera!', '2012-06-12 02:07:11.000000', NULL, 1),
(6792879, 1019879, 30982, '<td valign="top">Awesome catch!  This had to take a couple of tries.  Excellent wide, excellent exposure.  Who needs editing when you can do this?</td>', 'Awesome catch!  This had to take a couple of tries.  Excellent wide, excellent exposure.  Who needs editing when you can do this?', '2012-06-12 02:07:39.000000', NULL, 1),
(6792880, 1020035, 30982, '<td valign="top">Nice little caravan!  Good color and contrast but could be just a tad more defined on the vehicles, perhaps.</td>', 'Nice little caravan!  Good color and contrast but could be just a tad more defined on the vehicles, perhaps.', '2012-06-12 02:08:23.000000', NULL, 1),
(6792881, 1020092, 30982, '<td valign="top">Poor little guy!  Hope he got back to his regular home shortly after this!  Nice little story here.  Maybe just a bit less centered with the fish, but I do like the skyline beyond.</td>', 'Poor little guy!  Hope he got back to his regular home shortly after this!  Nice little story here.  Maybe just a bit less centered with the fish, but I do like the skyline beyond.', '2012-06-12 02:09:06.000000', NULL, 1),
(6792882, 1019968, 30982, '<td valign="top">Might not scream "wide angle" but it''s a cute shot - I especially like the half finished portrait!</td>', 'Might not scream "wide angle" but it''s a cute shot - I especially like the half finished portrait!', '2012-06-12 02:09:36.000000', NULL, 1),
(6792883, 1018849, 30982, '<td valign="top">A bit eerie because it seems so deserted.</td>', 'A bit eerie because it seems so deserted.', '2012-06-12 02:10:22.000000', NULL, 1),
(6792884, 1019317, 30982, '<td valign="top">Very nice job with the exposure and keeping your horizon level - the softness of the water is quite nice.</td>', 'Very nice job with the exposure and keeping your horizon level - the softness of the water is quite nice.', '2012-06-12 02:10:59.000000', NULL, 1),
(6792886, 1020079, 30982, '<td valign="top">Excellent!  Love wide with distortion (not enough of that in the challenge) and the motion is a nice added touch.  Especially like the gentleman outside to the right, almost keeping step with our young lady on the escalator.  A good wide story!</td>', 'Excellent!  Love wide with distortion (not enough of that in the challenge) and the motion is a nice added touch.  Especially like the gentleman outside to the right, almost keeping step with our young lady on the escalator.  A good wide story!', '2012-06-12 02:11:48.000000', NULL, 1),
(6792888, 1020050, 30982, '<td valign="top">Wonderful choice for the challenge - a nice wide expanse, lovely light, soft and gentle presentation.</td>', 'Wonderful choice for the challenge - a nice wide expanse, lovely light, soft and gentle presentation.', '2012-06-12 02:12:14.000000', NULL, 1),
(6792889, 1019880, 30982, '<td valign="top">I do get the sense of wide from this.  Good geometrics.  Maybe compose with the board on the right either straighter or dramatically skewed.  Sometimes really skewed compositions with wide can be fun to try.</td>', 'I do get the sense of wide from this.  Good geometrics.  Maybe compose with the board on the right either straighter or dramatically skewed.  Sometimes really skewed compositions with wide can be fun to try.', '2012-06-12 02:15:06.000000', NULL, 1),
