(6792891, 1020061, 30982, '<td valign="top">Ha!  Cute.  Not especially "wide" to me, but an interesting approach just the same.</td>', 'Ha!  Cute.  Not especially "wide" to me, but an interesting approach just the same.', '2012-06-12 02:15:58.000000', NULL, 1),
